    for j in range(4-i):
        mon.append(x**i*v**j)
def build(w):
    c_=np.cos(w*t); s_=np.sin(w*t)
    return np.column_stack(mon+[c_,s_,x*c_,x*s_,v*c_,v*s_,np.sin(x)*c_,np.sin(x)*s_,np.cos(x)*c_,np.cos(x)*s_])
def res(p):
    X=build(p[0]); c,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None); return X@c-dv_dt
best=None
for w0 in np.linspace(0.3,0.45,7):
    r=least_squares(res,[w0])
    e=np.mean(r.fun**2)/np.var(dv_dt)
    if best is None or e<best[0]: best=(e,r.x[0])
